const body = $input.first().json.body || $input.first().json;
const content = body.content || '';
const title = body.title || 'Untitled';
const source = body.source || 'unknown';

const now = new Date();
const date = now.toISOString().slice(0, 10);
const time = now.toISOString().slice(11, 19);
const slug = (title || 'capture')
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .slice(0, 40);

const filename = `${date}-${slug}.md`;
const filepath = `notes/01-inbox/${filename}`;

// Create raw capture file (unprocessed)
const rawCapture = [
  '---',
  'type: capture',
  `source: ${source}`,
  'status: unprocessed',
  `created: ${date}T${time}Z`,
  'confidence: null',
  'para_type: null',
  '---',
  '',
  `# ${title}`,
  '',
  '## Raw Content',
  content,
  '',
  '---',
  `*Raw capture saved at ${date}T${time}Z from ${source}*`,
  '*Awaiting Gemini classification...*'
].join('\n');

return [{
  json: {
    filepath,
    filename,
    content: rawCapture,
    title,
    source,
    date
  }
}];

