const body = $('Webhook').first().json.body || $('Webhook').first().json;
const source = body.source || 'chatgpt';
const title = body.title || 'Untitled';
const content = body.content || '';
const typeHint = body.type_hint || '';

const promptParts = [
  'You are processing a captured text for a personal knowledge management system using the PARA method.',
  '\n\nPARA definitions:',
  '\n- project: has a clear finish line (SaaS app, automation, specific deliverable)',
  '\n- area: ongoing responsibility, no end date (health, finance, business, personal development, ministry)',
  '\n- resource: reference material, research, learning, frameworks, how-to knowledge',
  '\n- inbox: unclear, mixed, needs more context',
  '\n\nContext about the owner:',
  '\n- Builds SaaS apps and business automations',
  '\n- Manages prochattools business (statuslink, xgrow, prochat, says-the-bible, probot)',
  '\n- Has Yeshua Academy (ministry work)',
  '\n- Goal: automate everything, optimise costs, work efficiently',
  `\n\nTitle hint: ${title}`,
  typeHint ? `\nType hint: ${typeHint}` : '',
  `\n\nConversation content:\n${content}`,
  '\n\nRespond ONLY with valid JSON, no markdown, no explanation:\n{\n  "title": "concise title max 6 words",\n  "para_type": "project|area|resource|inbox",\n  "confidence": 0.0,\n  "area_hint": "which life or business area",\n  "tags": ["tag1", "tag2"],\n  "summary": "2-3 sentence summary of the key insight or decision",\n  "key_points": ["point 1", "point 2", "point 3"],\n  "action_items": ["actionable task if any"],\n  "note_content": "full structured markdown body for the note, without frontmatter"\n}'
];

const geminiBody = JSON.stringify({
  contents: [{
    parts: [{ text: promptParts.join('') }]
  }]
});

return [{
  json: {
    title,
    content,
    type_hint: typeHint || null,
    source,
    geminiBody,
    filepath: $('Save Raw Capture').first().json.filepath
  }
}];

// If Gemini fails, data is already safe in GitHub
// Log the error and return gracefully
const error = $input.first().json;
return [{
  json: {
    status: 'gemini_failed',
    message: 'Gemini classification failed, but raw capture is safely stored in GitHub.',
    filepath: $('Build Gemini Body').first().json.filepath,
    error: error.message || 'Unknown error'
  }
}];

const geminiResponse = $input.first().json;
const filepath = $('Build Gemini Body').first().json.filepath;
const inputSource = $('Build Gemini Body').first().json.source;

const rawText = geminiResponse.candidates[0].content.parts[0].text;

// Strip markdown code fences
const stripped = rawText
  .replace(/^```json\s*/m, '')
  .replace(/^```\s*/m, '')
  .replace(/\s*```$/m, '')
  .trim();

// Sanitize JSON
function sanitizeJsonString(str) {
  let result = '';
  let inString = false;
  let escaped = false;
  for (let i = 0; i < str.length; i++) {
    const c = str[i];
    if (escaped) {
      result += c;
      escaped = false;
    } else if (c === '\\' && inString) {
      result += c;
      escaped = true;
    } else if (c === '"') {
      result += c;
      inString = !inString;
    } else if (inString && c === '\n') {
      result += '\\n';
    } else if (inString && c === '\r') {
      result += '\\r';
    } else if (inString && c === '\t') {
      result += '\\t';
    } else if (inString && c.charCodeAt(0) < 32) {
      result += '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0');
    } else {
      result += c;
    }
  }
  return result;
}

const cleanJson = sanitizeJsonString(stripped);
let parsed;
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    title: 'Unprocessed capture',
    para_type: 'inbox',
    confidence: 0,
    area_hint: '',
    tags: ['needs-review'],
    summary: 'Gemini could not process — review manually.',
    key_points: [],
    action_items: [],
    note_content: rawText
  };
}

const now = new Date();
const date = now.toISOString().slice(0, 10);

const tagsYaml = (parsed.tags || ['capture'])
  .map(t => `  - ${t}`).join('\n');

const frontmatter = [
  '---',
  'type: capture',
  `source: ${inputSource}`,
  `para_type: ${parsed.para_type || 'inbox'}`,
  `confidence: ${parsed.confidence || 0}`,
  `area: ${parsed.area_hint || ''}`,
  'status: processed',
  `created: ${date}`,
  'tags:',
  tagsYaml,
  '---'
].join('\n');

const keyPoints = (parsed.key_points || []).map(p => `- ${p}`).join('\n') || '-';
const actionItems = (parsed.action_items || []).map(a => `- [ ] ${a}`).join('\n');
const confidence = Math.round((parsed.confidence || 0) * 100);

const noteBody = [
  frontmatter,
  '',
  `# ${parsed.title}`,
  '',
  '## Summary',
  parsed.summary || '',
  '',
  '## Key Points',
  keyPoints,
  '',
  actionItems ? `## Action Items\n${actionItems}\n` : '',
  '## Notes',
  parsed.note_content || '',
  '',
  '---',
  `*Capture · ${date} · ${confidence}% confidence · suggested: ${parsed.para_type}*`,
  `*Review in [[home|Command Center]] — promote to [[notes/projects/|projects]], [[notes/areas/|areas]], or [[notes/resources/|resources]]*`
].join('\n');

return [{
  json: {
    filepath,
    content: noteBody,
    title: parsed.title,
    para_type: parsed.para_type,
    confidence: parsed.confidence
  }
}];
